(45411, 'Psalms 119:100', 'Psalms', 119, 100, 'زه له مشرانو څخه زیات پوهېږم ځکه چې کړمه عمل ستا په اصولو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms119_verse_100.mp3', '', 1761754199, 1761754199),
(45412, 'Psalms 119:101', 'Psalms', 119, 101, 'د بدو لارو مې ساتلي قدمونه خپل ځکه زه غواړم عمل وکړم ستا په کلام باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms119_verse_101.mp3', '', 1761754199, 1761754199),
(45413, 'Psalms 119:102', 'Psalms', 119, 102, 'ستا قوانین مې له نظره غورځولي نه دي ځکه چې تا راته زده کړي هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms119_verse_102.mp3', '', 1761754199, 1761754199),
(45414, 'Psalms 119:103', 'Psalms', 119, 103, 'دا ستا کلام دی څومره خوږ ماته حتی د شاتو نه هم زیات خوږ دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms119_verse_103.mp3', '', 1761754199, 1761754199),
