(45480, 'Psalms 119:169', 'Psalms', 119, 169, 'زما د مرستې فریادونه دې ای څښتنه تاته درورسیږي خپلې وعدې سره دې سم ماته پوهه راکړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms119_verse_169.mp3', '', 1761754199, 1761754199),
(45481, 'Psalms 119:170', 'Psalms', 119, 170, 'زما زاري دې تاته درورسیږي خپلې وعدې سره دې سم ماته نجات راکړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms119_verse_170.mp3', '', 1761754199, 1761754199),
(45482, 'Psalms 119:171', 'Psalms', 119, 171, 'زما په ژبه به وي ستا ثنا او صفت ځکه چې ماته زده کوې خپل قوانین', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms119_verse_171.mp3', '', 1761754199, 1761754199),
(45483, 'Psalms 119:172', 'Psalms', 119, 172, 'زه به سندره وایم ستا د کلام په هکله ځکه چې دي عادلانه ټول حکمونه ستا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms119_verse_172.mp3', '', 1761754199, 1761754199),
(45484, 'Psalms 119:173', 'Psalms', 119, 173, 'ماته لاس د مرستې راکړه ځکه چې ما دا غوره کړې چې پیروي کومه ستا له اصولو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms119_verse_173.mp3', '', 1761754199, 1761754199),
(45485, 'Psalms 119:174', 'Psalms', 119, 174, 'زه په ارمان ستا د نجات یمه ای څښتنه ستا په شریعت کې خوشحالي ده زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms119_verse_174.mp3', '', 1761754199, 1761754199),
(45486, 'Psalms 119:175', 'Psalms', 119, 175, 'ژوندی مې پرېږده چې ثنا دې وایم ستا قوانین دې زما مرسته وکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms119_verse_175.mp3', '', 1761754199, 1761754199),
(45487, 'Psalms 119:176', 'Psalms', 119, 176, 'لکه ورک شوی پسه زه سرګردانه یمه راشه او ولټوه خپل خدمتګار ځکه چې ما هېر کړي نه دي حکمونه ستا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms119_verse_176.mp3', '', 1761754199, 1761754199),
(45488, 'Jeremiah 33:1', 'Jeremiah', 33, 1, 'يرمياه چې لا د فوجيانو په چاوڼۍ کښې بند وو نو د مالِک خُدائ پېغام په دوېم ځل هغۀ ته راغلو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_1.mp3', '', 1761754199, 1761754199),
(45489, 'Jeremiah 33:2', 'Jeremiah', 33, 2, '”مالِک خُدائ چا چې، زمکه جوړه کړه، او هغې ته يې شکل ورکړو او قائمه يې کړه او د چا نوم چې مالِک خُدائ دے هغه فرمائى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_2.mp3', '', 1761754199, 1761754199),
(45490, 'Jeremiah 33:3', 'Jeremiah', 33, 3, 'د مدد دپاره ما ته ووايه او زۀ به جواب درکړم او زۀ به تا ته هغه لوئ او پټ رازونه او خبرې څرګندې کړم چې تۀ پرې نۀ پوهېږې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_3.mp3', '', 1761754199, 1761754199),
(45491, 'Jeremiah 33:4', 'Jeremiah', 33, 4, 'نو مالِک خُدائ د بنى اِسرائيلو خُدائ پاک داسې فرمائى چې، تاسو د ښار کورونه او تر دې چې شاهى محل هم راوغورزولو د دې دپاره چې د دشمن د محاصرې او حملې په وخت کښې تاسو د هغې په ملبې خپل د خاورو ډېرو دېوالونه مضبوط کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_4.mp3', '', 1761754199, 1761754199),
(45492, 'Jeremiah 33:5', 'Jeremiah', 33, 5, 'د بابليانو سره په جنګ کولو کښې به دا ښار او د دې کورونه د خلقو د مړو د لاشونو نه ډک کړم. زۀ به دوئ په خپل قهر او غضب کښې تباه کړم. زۀ به د دې ښار نه د دوئ د ګناهونو په وجه خپل مخ پټ کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_5.mp3', '', 1761754199, 1761754199),
(45493, 'Jeremiah 33:6', 'Jeremiah', 33, 6, 'خو باوجود د دې به هغه وخت راشى چې زۀ به د يروشلم زخمونو ته شفا ورکړم او هغې ته به حقيقى امن او سکون ورکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_6.mp3', '', 1761754199, 1761754199),
(45494, 'Jeremiah 33:7', 'Jeremiah', 33, 7, 'زۀ به يهوداه او اِسرائيل د غلامۍ نه واپس راولم او هغوئ به بيا هغه شان آباد کړم لکه څنګه چې هغوئ وړاندې وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_7.mp3', '', 1761754199, 1761754199),
(45495, 'Jeremiah 33:8', 'Jeremiah', 33, 8, 'زۀ به هغوئ د هغه ټولو ګناهونو نه پاک کړم کوم چې هغوئ زما خِلاف کړى دى، او زۀ به د هغوئ هغه سرکشى معاف کړم کومه چې هغوئ زما خلاف کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_8.mp3', '', 1761754199, 1761754199),
(45496, 'Jeremiah 33:9', 'Jeremiah', 33, 9, 'نو بيا به دا ښار ما ته د ټولې دُنيا د خلقو په وړاندې خوشحالى، شُهرت، او عزت راکړى، کله چې دوئ د هغه ټولو ښۀ څيزونو په حقله واورى کوم چې زۀ د يروشلم سره کوم. او خلق به د دې ټول امن او آبادۍ نه متاثره شى او د يرې نه به په لړزان شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_9.mp3', '', 1761754199, 1761754199),
(45497, 'Jeremiah 33:10', 'Jeremiah', 33, 10, 'مالِک خُدائ فرمائى چې، تاسو د دې ځائ په حقله وايئ چې، دا ځائ خو د صحرا په شان دے چې په کښې نه انسان او نه ځناور شته. خو د يهوداه ښارونه او د يروشلم کوڅې خالى دى کومې چې په ميرو بدلې شوې چې نۀ په کښې انسان او نۀ په کښې ځناور شته، نو يو ځل بيا به هلته،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_10.mp3', '', 1761754199, 1761754199),
(45498, 'Jeremiah 33:11', 'Jeremiah', 33, 11, 'د خوشحالۍ او د خندا آوازونه واورېدلے شى او په کښې به د ناوې او د زلمى آوازونه واورېدلے شى، او د هغوئ آوازونه چې د مالِک خُدائ په کور کښې د شکرانې نذرانې پېش کوى، واورېدلے شى. او هغوئ به داسې وائى چې، د مالِک خُدائ ربُ الافواج شُکر ګزارى وکړئ، ځکه چې هغه ښۀ دے، د هغۀ مينه نۀ ختمېدونکې ده. مالِک خُدائ دا فرمائى چې، زۀ به دا مُلک د غلامۍ نه واپس راولم لکه څنګه چې وړاندې وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_11.mp3', '', 1761754199, 1761754199),
(45499, 'Jeremiah 33:12', 'Jeremiah', 33, 12, 'مالِک خُدائ ربُ الافواج فرمائى، کۀ څۀ هم چې دا مُلک اوس د صحرا په شان دے او د انسانانو او ځناورو نه خالى دے خو په دې کښې به بيا د څرن زمکه راپېدا شى چې شپونکى به ورته خپلې رمې څرولو دپاره راولى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_12.mp3', '', 1761754199, 1761754199),
(45500, 'Jeremiah 33:13', 'Jeremiah', 33, 13, 'مالِک خُدائ فرمائى چې، د غريزه مُلک په ښارونو، او د غونډو په شا او خوا، او د نجب په صحرا، د بنيامين په علاقه کښې، د يروشلم په شا او خوا، او د يهوداه په ښارونو کښې به شپونکى يو ځل بيا خپل ګډورى وشمارى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_13.mp3', '', 1761754199, 1761754199),
(45501, 'Jeremiah 33:14', 'Jeremiah', 33, 14, 'مالِک خُدائ فرمائى چې، هغه وخت راتلونکے دے چې زۀ به خپله هغه مهربانه وعده پوره کړم چې کومه ما د يهوداه او د اِسرائيل سره کړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_14.mp3', '', 1761754199, 1761754199),
(45502, 'Jeremiah 33:15', 'Jeremiah', 33, 15, 'په هغه وخت کښې به زۀ د داؤد د اولاد نه يوه صادقه څانګه راوټوکوم، هغه به په ټول مُلک کښې هغه کارونه کوى کوم چې د اِنصاف او صداقت وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_15.mp3', '', 1761754199, 1761754199),
(45503, 'Jeremiah 33:16', 'Jeremiah', 33, 16, 'په هغه ورځو کښې به يهوداه بچ کړے شى او يروشلم به د سلامتۍ سره ژوند کوى. او دا هغه نوم دے چې په کوم سره به هغه ياديږى، مالِک خُدائ زمونږ خلاصونکے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_16.mp3', '', 1761754199, 1761754199),
(45504, 'Jeremiah 33:17', 'Jeremiah', 33, 17, 'مالِک خُدائ داسې فرمائى چې، د داؤد په اولاد کښې به همېشه يو کس د بنى اِسرائيلو په تخت ناست وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_17.mp3', '', 1761754199, 1761754199),
(45505, 'Jeremiah 33:18', 'Jeremiah', 33, 18, 'او هم داسې به اِمامان همېشه د ليوى قبيلې نه وى څوک به چې تل زما خِدمت کوى او ما ته به سوزېدونکې نذرانې، او د غلو نذرانې او قربانۍ پېش کوى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_18.mp3', '', 1761754199, 1761754199),
(45506, 'Jeremiah 33:19', 'Jeremiah', 33, 19, 'نو بيا د مالِک خُدائ پېغام يرمياه ته راغلو چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_19.mp3', '', 1761754199, 1761754199),
(45507, 'Jeremiah 33:20', 'Jeremiah', 33, 20, '”مالِک خُدائ فرمائى چې، کۀ چرې تاسو زما لوظ د ورځې او د شپې د مقرر شوى نظام په حقله ماتولے شئ، چې شپه او ورځ په خپل مقرر شوى وخت رانۀ شى', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_20.mp3', '', 1761754199, 1761754199),
(45508, 'Jeremiah 33:21', 'Jeremiah', 33, 21, 'نو بيا به هغه وخت زما لوظ زما د خِدمتګار داؤد سره او زما لوظ د ليويانو سره چې زما اِمامان دى او زما په حضور کښې خِدمت کوى به هم ماتېدے شى، نو بيا به د داؤد اولاد کښې نور څوک نۀ وى چې د هغۀ په تخت بادشاهى وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_21.mp3', '', 1761754199, 1761754199),
(45509, 'Jeremiah 33:22', 'Jeremiah', 33, 22, 'زۀ به د خپل خِدمتګار داؤد نسل او ليويان کوم چې زما اِمامان دى او زما په وړاندې خِدمت کوى د آسمان د ستورو او د سمندر د شګو په شان بې‌شمېره زيات کړم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_22.mp3', '', 1761754199, 1761754199),
(45510, 'Jeremiah 33:23', 'Jeremiah', 33, 23, 'مالِک خُدائ بل پېغام يرمياه ته ورکړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah33_verse_23.mp3', '', 1761754199, 1761754199);